<template>
  <div class="app-container">
    <el-form :model="query" :inline="true"><el-form-item label="订单编号"><el-input v-model="query.orderNo" clearable /></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option v-for="item in orderStatuses" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="loadData">查询</el-button><el-button v-hasPermi="['digital:order:add']" type="primary" icon="Plus" @click="openCreate">创建订单</el-button></el-form-item></el-form>
    <el-table v-loading="loading" :data="rows"><el-table-column prop="orderNo" label="订单编号" width="180" /><el-table-column prop="customerName" label="客户" /><el-table-column prop="totalAmount" label="订单金额" /><el-table-column label="状态"><template #default="{ row }"><dict-tag :options="orderStatuses" :value="row.status" /></template></el-table-column><el-table-column prop="createTime" label="创建时间" width="180" /><el-table-column label="操作" width="340"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row)">详情</el-button><el-button v-if="row.status === 'DRAFT'" v-hasPermi="['digital:order:edit']" link type="primary" @click="openEdit(row)">编辑</el-button><el-button v-if="row.status === 'DRAFT'" v-hasPermi="['digital:order:confirm']" link type="success" @click="confirm(row)">确认销售</el-button><el-button v-if="['DRAFT','CONFIRMED'].includes(row.status)" v-hasPermi="['digital:order:cancel']" link type="danger" @click="cancel(row)">取消</el-button><el-button v-if="row.status === 'CONFIRMED'" v-hasPermi="['digital:order:complete']" link type="success" @click="complete(row)">完成</el-button><el-button v-if="row.status === 'DRAFT'" v-hasPermi="['digital:order:remove']" link type="danger" @click="removeDraft(row)">删除</el-button></template></el-table-column></el-table>
    <pagination v-show="total > 0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="loadData" />

    <el-dialog v-model="createVisible" title="创建草稿订单" width="760px"><el-form ref="createRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="客户" prop="customerId"><el-select v-model="form.customerId" filterable style="width:100%"><el-option v-for="item in customers" :key="item.customerId" :label="`${item.customerName} ${item.phone || ''}`" :value="item.customerId" /></el-select></el-form-item><el-form-item label="请求号"><el-input v-model="form.requestNo" disabled /></el-form-item><el-divider content-position="left">订单明细</el-divider><div v-for="(item,index) in form.items" :key="index" class="item-row"><el-select v-model="item.skuId" filterable placeholder="选择商品规格" @change="value => selectSku(item, value)"><el-option v-for="sku in skus" :key="sku.skuId" :label="`${sku.productName} / ${sku.skuName}（库存 ${sku.stock}）`" :value="sku.skuId" /></el-select><el-input-number v-model="item.salePrice" :min="0" :precision="2" /><el-input-number v-model="item.quantity" :min="1" /><el-button v-if="form.items.length > 1" link type="danger" @click="form.items.splice(index,1)">移除</el-button></div><el-button link type="primary" @click="form.items.push(newItem())">+ 添加商品</el-button></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" @click="submitCreate">保存草稿</el-button></template></el-dialog>

    <el-dialog v-model="detailVisible" title="订单详情" width="820px"><el-descriptions :column="2" border><el-descriptions-item label="订单编号">{{ detail.orderNo }}</el-descriptions-item><el-descriptions-item label="客户">{{ detail.customerName }}</el-descriptions-item><el-descriptions-item label="订单金额">{{ detail.totalAmount }}</el-descriptions-item><el-descriptions-item label="状态">{{ statusText(detail.status) }}</el-descriptions-item></el-descriptions><el-table :data="detail.items || []" class="detail-table"><el-table-column prop="productName" label="商品" /><el-table-column prop="skuName" label="规格" /><el-table-column prop="salePrice" label="成交价" /><el-table-column prop="quantity" label="数量" /><el-table-column prop="refundedQuantity" label="已退数量" /><el-table-column v-if="detail.status === 'COMPLETED'" label="售后"><template #default="{ row }"><el-button link type="primary" @click="openAfterSale(row)">申请售后</el-button></template></el-table-column></el-table></el-dialog>

    <el-dialog v-model="afterSaleVisible" title="创建售后工单" width="500px"><el-form ref="afterSaleRef" :model="afterSaleForm" :rules="afterSaleRules" label-width="100px"><el-form-item label="商品"><el-input :model-value="`${afterSaleItem.productName || ''} / ${afterSaleItem.skuName || ''}`" disabled /></el-form-item><el-form-item label="售后类型" prop="ticketType"><el-select v-model="afterSaleForm.ticketType"><el-option label="退货" value="RETURN" /><el-option label="维修" value="REPAIR" /></el-select></el-form-item><el-form-item label="申请数量" prop="applyQuantity"><el-input-number v-model="afterSaleForm.applyQuantity" :min="1" :max="afterSaleMax" /></el-form-item><el-form-item label="问题描述" prop="faultDesc"><el-input v-model="afterSaleForm.faultDesc" type="textarea" maxlength="500" show-word-limit /></el-form-item></el-form><template #footer><el-button @click="afterSaleVisible=false">取消</el-button><el-button type="primary" @click="submitAfterSale">提交申请</el-button></template></el-dialog>
  </div>
</template>
<script setup name="DigitalOrder">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { listOrder, addOrder, getOrder, updateOrder, confirmOrder, cancelOrder, completeOrder, deleteOrder } from '@/api/digital/order'
import { listCustomer } from '@/api/digital/customer'
import { listSku } from '@/api/digital/sku'
import { addAfterSale } from '@/api/digital/aftersale'
const orderStatuses=[{label:'草稿',value:'DRAFT',listClass:'info'},{label:'已确认',value:'CONFIRMED',listClass:'primary'},{label:'已完成',value:'COMPLETED',listClass:'success'},{label:'已取消',value:'CANCELLED',listClass:'danger'}]
const loading=ref(false),rows=ref([]),total=ref(0),query=reactive({pageNum:1,pageSize:10,orderNo:undefined,status:undefined})
const createVisible=ref(false),createRef=ref(),editing=ref(false),customers=ref([]),skus=ref([]),form=reactive({orderId:undefined,requestNo:'',customerId:undefined,items:[]})
const rules={customerId:[{required:true,message:'请选择客户'}]},detailVisible=ref(false),detail=reactive({})
const afterSaleVisible=ref(false),afterSaleRef=ref(),afterSaleItem=reactive({}),afterSaleForm=reactive({orderItemId:undefined,ticketType:'RETURN',applyQuantity:1,faultDesc:''})
const afterSaleMax=computed(()=>Math.max(1,(afterSaleItem.quantity||1)-(afterSaleItem.refundedQuantity||0)))
const afterSaleRules={ticketType:[{required:true,message:'请选择售后类型'}],applyQuantity:[{required:true,message:'请输入申请数量'}],faultDesc:[{required:true,message:'请输入问题描述',trigger:'blur'}]}
function newItem(){return{skuId:undefined,salePrice:0,quantity:1}}
function loadData(){loading.value=true;listOrder(query).then(res=>{rows.value=res.rows||[];total.value=res.total||0}).finally(()=>loading.value=false)}
function loadOptions(){return Promise.all([listCustomer({pageNum:1,pageSize:200,status:'0'}),listSku({pageNum:1,pageSize:500,status:'0'})]).then(([c,s])=>{customers.value=c.rows||[];skus.value=(s.rows||[]).filter(item=>item.stock>0)})}
function openCreate(){editing.value=false;Object.assign(form,{orderId:undefined,requestNo:`WEB-${Date.now()}`,customerId:undefined,items:[newItem()]});loadOptions().then(()=>createVisible.value=true)}
function openEdit(row){editing.value=true;Promise.all([loadOptions(),getOrder(row.orderId)]).then(([,res])=>{Object.assign(form,{orderId:res.data.orderId,requestNo:res.data.requestNo,customerId:res.data.customerId,items:(res.data.items||[]).map(item=>({itemId:item.itemId,skuId:item.skuId,salePrice:Number(item.salePrice),quantity:item.quantity}))});createVisible.value=true})}
function selectSku(item,id){const sku=skus.value.find(x=>x.skuId===id);if(sku)item.salePrice=Number(sku.salePrice||0)}
async function submitCreate(){await createRef.value.validate();if(form.items.some(item=>!item.skuId))return ElMessage.warning('请选择订单商品');const payload={orderId:form.orderId,requestNo:form.requestNo,customerId:form.customerId,items:form.items};const action=editing.value?updateOrder(payload):addOrder(payload);action.then(()=>{ElMessage.success(editing.value?'草稿订单修改成功':'草稿订单创建成功');createVisible.value=false;loadData()})}
function showDetail(row){getOrder(row.orderId).then(({data})=>{Object.assign(detail,data||{});detailVisible.value=true})}
function runAction(message,api,row){ElMessageBox.confirm(message,'提示',{type:'warning'}).then(()=>api(row.orderId)).then(()=>{ElMessage.success('操作成功');loadData()})}
function confirm(row){runAction('确认销售后将扣减库存，是否继续？',confirmOrder,row)}
function cancel(row){runAction('确认取消该订单吗？',cancelOrder,row)}
function complete(row){runAction('确认订单已经交付完成吗？',completeOrder,row)}
function removeDraft(row){ElMessageBox.confirm('确认删除该草稿订单吗？','提示',{type:'warning'}).then(()=>deleteOrder(row.orderId)).then(()=>{ElMessage.success('草稿订单已删除');loadData()})}
function statusText(status){return(orderStatuses.find(item=>item.value===status)||{}).label||status}
function openAfterSale(item){Object.assign(afterSaleItem,item);Object.assign(afterSaleForm,{orderItemId:item.itemId,ticketType:'RETURN',applyQuantity:1,faultDesc:''});afterSaleVisible.value=true}
async function submitAfterSale(){await afterSaleRef.value.validate();addAfterSale(afterSaleForm).then(()=>{ElMessage.success('售后申请创建成功');afterSaleVisible.value=false;detailVisible.value=false})}
onMounted(loadData)
</script>
<style scoped>.item-row{display:grid;grid-template-columns:2fr 140px 120px 60px;gap:12px;margin-bottom:12px}.detail-table{margin-top:18px}</style>
